  var custom = (window.CFG && CFG.subUrl) ? String(CFG.subUrl).trim().replace(/^\/+/, '').replace(/\/+$/, '').replace(/\/sub$/i, '') : '';
  if (custom && !/^[A-Za-z0-9]{3,64}$/.test(custom)) custom = '';
